export function transpose(m: number[][]): number[][] {
  if (m.length === 0) return [];
  const cols = m[0].length;
  const out: number[][] = [];
  for (let c = 0; c < cols; c++) {
    const col: number[] = [];
    for (const row of m) col.push(row[c]);
    out.push(col);
  }
  return out;
}
